package search
import("context";"image";"image/color";"image/jpeg";"os";"path/filepath";"testing";"imgsearch/internal/cache";"imgsearch/internal/imgutil")
func reviewJPEG(t *testing.T,path string,reverse bool,solid bool){t.Helper();im:=image.NewRGBA(image.Rect(0,0,64,64));for y:=0;y<64;y++{for x:=0;x<64;x++{v:=uint8(x*4);if reverse{v=252-v};if solid{v=0};im.SetRGBA(x,y,color.RGBA{v,v,v,255})}};f,e:=os.Create(path);if e!=nil{t.Fatal(e)};if e=jpeg.Encode(f,im,&jpeg.Options{Quality:95});e!=nil{t.Fatal(e)};if e=f.Close();e!=nil{t.Fatal(e)}}
func TestReviewTopOneIsFirstNotBest(t *testing.T){root:=t.TempDir();dir:=filepath.Join(root,"candidates");os.Mkdir(dir,0700);query:=filepath.Join(root,"query.jpg");reviewJPEG(t,query,false,false);first:=filepath.Join(dir,"a-worse.jpg");best:=filepath.Join(dir,"z-best.jpg");reviewJPEG(t,first,false,true);reviewJPEG(t,best,false,false);source:=imgutil.LoadAndHash(query);worse:=imgutil.ComputeSimilarity(source,imgutil.LoadAndHash(first));better:=imgutil.ComputeSimilarity(source,imgutil.LoadAndHash(best));if worse>=better{t.Fatalf("fixture ordering invalid %f %f",worse,better)};var matches []Result;Run(context.Background(),source,Config{SearchDir:dir,Threshold:0,Workers:1,TopN:1},func(r Result){if !r.Done{matches=append(matches,r)}});if len(matches)!=1||matches[0].Match.Path!=first{t.Fatalf("expected observed first-match selection: %+v",matches)};t.Logf("TopN1 selected %.3f while later candidate %.3f",worse,better)}
func TestReviewRestoredMtimeStale(t *testing.T){root:=t.TempDir();path:=filepath.Join(root,"image.jpg");reviewJPEG(t,path,false,false);before,e:=os.Stat(path);if e!=nil{t.Fatal(e)};old:=imgutil.LoadAndHash(path);c,e:=cache.New(filepath.Join(root,"cache.db"));if e!=nil{t.Fatal(e)};defer c.Close();if e=c.Put(path,before.ModTime(),&old);e!=nil{t.Fatal(e)};reviewJPEG(t,path,true,false);if e=os.Chtimes(path,before.ModTime(),before.ModTime());e!=nil{t.Fatal(e)};after,e:=os.Stat(path);if e!=nil{t.Fatal(e)};fresh:=imgutil.LoadAndHash(path);if fresh.Error!=nil||fresh.DHash==old.DHash{t.Fatal("fixture must change hash")};cached,ok:=c.Get(path,after.ModTime());if !ok||cached.DHash!=old.DHash{t.Fatal("expected observed stale cache hit")};t.Logf("mtime equal=%v sizes %d/%d old=%x fresh=%x cached=%x",before.ModTime().Equal(after.ModTime()),before.Size(),after.Size(),old.DHash,fresh.DHash,cached.DHash)}
